const bit<16> ETHERTYPE_ARP = 0x0806;
const bit<16> ETHERTYPE_IPV4 = 0x0800;
const bit<16> ETHERTYPE_VLAN = 0x8100;
const bit<16> ETHERTYPE_QINQ = 0x88A8;

typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header vlan_tag_t {
    bit<12> priority : 3;
    bit<1> cfi : 1;
    bit<1> vid : 12;
}

header arp_t {
    bit<16> htype;
    bit<16> ptype;
    bit<8> hlen;
    bit<8> plen;
    bit<16> operation;
    macAddr_t sha;
    ip4Addr_t spa;
    macAddr_t tha;
    ip4Addr_t tpa;
}

header ipv4_t {
    bit<4> version;
    bit<4> ihl;
    bit<6> diffserv;
    bit<2> ecn;
    bit<16> totalLen;
    bit<16> identification;
    bit<3> flags;
    bit<13> fragOffset;
    bit<8> ttl;
    bit<8> protocol;
    bit<16> hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header myTunnel_t {
    bit<16> proto_id;
    bit<16> dst_id;
}

struct metadata {
    counter packets;
    counter bytes;
    hash<macAddr_t> macTable;
    bool isVlanTagged;
    bit<16> ingressPort;
}

struct headers {
    ethernet_t   ethernet;
    vlan_tag_t   vlanTag;
    arp_t        arp;
    ipv4_t       ipv4;
    myTunnel_t   myTunnel;
}

parser MyParser(packet_in packet,
                 out headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            ETHERTYPE_VLAN: parse_vlan;
            ETHERTYPE_QINQ: parse_qinq;
            ETHERTYPE_ARP: parse_arp;
            ETHERTYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_vlan {
        packet.extract(hdr.vlanTag);
        packet.extract(hdr.ethernet);
        transition accept;
    }

    state parse_qinq {
        packet.extract(hdr.vlanTag);
        packet.extract(hdr.ethernet);
        transition accept;
    }

    state parse_arp {
        packet.extract(hdr.arp);
        transition accept;
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action learn_port(bit<9> port) {
        meta.ingressPort = port;
        meta.macTable.insert(hdr.ethernet.srcAddr, port);
    }

    action forward(macAddr_t dstAddr, bit<9> port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action set_vlan(bit<16> tag) {
        hdr.vlanTag.vid = tag;
        hdr.ethernet.etherType = ETHERTYPE_VLAN;
        meta.isVlanTagged = true;
    }

    action remove_vlan() {
        hdr.ethernet.etherType = hdr.ipv4.proto;
        meta.isVlanTagged = false;
    }

    action set_qinq(bit<16> outer_tag, bit<16> inner_tag) {
        hdr.vlanTag.vid = outer_tag;
        hdr.ethernet.etherType = ETHERTYPE_QINQ;
        hdr.vlanTag.cfi = 0;
        hdr.vlanTag.priority = 0;
        hdr.vlanTag.vid = inner_tag;
        hdr.ethernet.etherType = ETHERTYPE_VLAN;
        meta.isVlanTagged = true;
    }

    action remove_qinq() {
        hdr.ethernet.etherType = hdr.ipv4.proto;
        meta.isVlanTagged = false;
    }

    table mac_learn {
        key = {
            hdr.ethernet.srcAddr: exact;
        }
        actions = {
            learn_port;
            NoAction;
        }
        size = 512;
        default_action = NoAction();
    }

    table mac_table {
        key = {
            hdr.ethernet.dstAddr: exact;
            meta.ingressPort: exact;
        }
        actions = {
            forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    table vlan_table {
        key = {
            hdr.ethernet.dstAddr: exact;
            meta.ingressPort: exact;
        }
        actions = {
            set_vlan;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    table qinq_table {
        key = {
            hdr.ethernet.dstAddr: exact;
            meta.ingressPort: exact;
        }
        actions = {
            set_qinq;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    apply {
        if (hdr.ethernet.isValid()) {
            mac_learn.apply();
        }
        if (hdr.ipv4.isValid()) {
            if (!meta.isVlanTagged && !meta.isVlanTagged) {
                mac_table.apply();
            } else if (meta.isVlanTagged) {
                vlan_table.apply();
            } else if (meta.isVlanTagged) {
                qinq_table.apply();
            }
        }
    }
}

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {
        if (hdr.vlanTag.isValid()) {
            hdr.ethernet.etherType = ETHERTYPE_VLAN;
        }
        if (hdr.myTunnel.isValid()) {
            hdr.ethernet.etherType = hdr.myTunnel.proto_id;
        }
    }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.ecn,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.vlanTag);
        packet.emit(hdr.arp);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.myTunnel);
    }
}

V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

